select null, t.id, 'builtin', 'The reagent strip test for urine protein is based on the principle of:', '["Diazo reaction","Protein error of indicators","Pseudoperoxidase activity","Sodium nitroprusside reaction"]'::jsonb, 1, 'The standard protein pad uses tetrabromophenol blue dye, which changes color when protein binds (the protein error of indicators). Diazo = bilirubin, pseudoperoxidase = blood, nitroprusside = ketones. Reference: Measurement of the albumin content of urinary protein using dipsticks (pmc.ncbi.nlm.nih.gov/articles/PMC6807921).', '["Used for bilirubin and nitrite pads.","Protein (mainly albumin) changes the indicator color at a fixed pH.","Used for the blood pad.","Used for the ketone pad."]'::jsonb, 1, 'verified'
