insert into questions (owner_id, topic_id, source, stem, choices, correct_index, explanation, choice_notes, difficulty, status)
select null, t.id, 'builtin', 'Normal urine specific gravity ranges from about:', '["1.000 to 1.002","1.003 to 1.030","1.035 to 1.050","Always exactly 1.010"]'::jsonb, 1, 'Normal urine specific gravity ranges from 1.003 to 1.030. A value fixed at about 1.010 (isosthenuria) suggests the kidney cannot concentrate or dilute urine. Reference: Simerville et al., Urinalysis: A Comprehensive Review, AFP 2005 (aafp.org/pubs/afp/issues/2005/0315/p1153.html).', '["Too dilute for a normal random sample.","Random urine range; first morning urine is usually higher.","Too high; suggests contrast media or another substance.","That is isosthenuria, not normal."]'::jsonb, 1, 'verified'
