insert into questions (owner_id, topic_id, source, stem, choices, correct_index, explanation, choice_notes, difficulty, status)
select null, t.id, 'builtin', 'The reagent strip glucose test is based on:', '["Copper reduction","Glucose oxidase reaction","Protein error of indicators","Diazo reaction"]'::jsonb, 1, 'The strip glucose pad uses glucose oxidase, and no urine components are known to cause false-positive glucose oxidase reactions. Copper reduction is the Clinitest principle; diazo is for bilirubin. Reference: Delanghe & Speeckaert, Preanalytical requirements of urinalysis, Biochem Med 2014 (pmc.ncbi.nlm.nih.gov/articles/PMC3936984).', '["That is Clinitest (Benedict''s principle).","Glucose oxidase and peroxidase are specific for glucose.","That is the protein pad.","That is the bilirubin pad."]'::jsonb, 1, 'verified'
from topics t join subjects s on s.id = t.subject_id
where s.code = 'CM' and t.name = 'Chemical Exam of Urine'
  and not exists (select 1 from questions x where x.owner_id is null and x.stem_hash = md5(trim(regexp_replace(regexp_replace(lower('The reagent strip glucose test is based on:'), '[^a-z0-9 ]', ' ', 'g'), '\s+', ' ', 'g'))));
update questions set choice_notes = '["That is Clinitest (Benedict''s principle).","Glucose oxidase and peroxidase are specific for glucose.","That is the protein pad.","That is the bilirubin pad."]'::jsonb
where owner_id is null and choice_notes is null and choices = '["Copper reduction","Glucose oxidase reaction","Protein error of indicators","Diazo reaction"]'::jsonb and stem_hash = md5(trim(regexp_replace(regexp_replace(lower('The reagent strip glucose test is based on:'), '[^a-z0-9 ]', ' ', 'g'), '\s+', ' ', 'g')));
insert into questions (owner_id, topic_id, source, stem, choices, correct_index, explanation, choice_notes, difficulty, status)
select null, t.id, 'builtin', 'An infant has a positive Clinitest (reducing substances) but a negative reagent strip glucose. This suggests:', '["Diabetes mellitus","Renal glycosuria","Galactosemia","Phenylketonuria"]'::jsonb, 2, 'Clinitest reacts with reducing sugars such as galactose, while the glucose oxidase strip reacts only with glucose. A positive Clinitest in this setting suggests galactosemia. Reference: A case of galactosemia misdiagnosed as cow''s milk intolerance (pmc.ncbi.nlm.nih.gov/articles/PMC3462687); Delanghe & Speeckaert, Preanalytical requirements of urinalysis, Biochem Med 2014 (pmc.ncbi.nlm.nih.gov/articles/PMC3936984).', '["Strip would also be positive.","Strip would also be positive.","Galactose is a reducing sugar but not detected by glucose oxidase.","Does not give reducing substances."]'::jsonb, 1, 'verified'
from topics t join subjects s on s.id = t.subject_id
where s.code = 'CM' and t.name = 'Chemical Exam of Urine'
  and not exists (select 1 from questions x where x.owner_id is null and x.stem_hash = md5(trim(regexp_replace(regexp_replace(lower('An infant has a positive Clinitest (reducing substances) but a negative reagent strip glucose. This suggests:'), '[^a-z0-9 ]', ' ', 'g'), '\s+', ' ', 'g'))));
update questions set choice_notes = '["Strip would also be positive.","Strip would also be positive.","Galactose is a reducing sugar but not detected by glucose oxidase.","Does not give reducing substances."]'::jsonb
where owner_id is null and choice_notes is null and choices = '["Diabetes mellitus","Renal glycosuria","Galactosemia","Phenylketonuria"]'::jsonb and stem_hash = md5(trim(regexp_replace(regexp_replace(lower('An infant has a positive Clinitest (reducing substances) but a negative reagent strip glucose. This suggests:'), '[^a-z0-9 ]', ' ', 'g'), '\s+', ' ', 'g')));
insert into questions (owner_id, topic_id, source, stem, choices, correct_index, explanation, choice_notes, difficulty, status)
select null, t.id, 'builtin', 'The sodium nitroprusside ketone pad does NOT detect:', '["Acetoacetic acid","Acetone","Beta-hydroxybutyric acid","It detects all three"]'::jsonb, 2, 'Strip ketone tests use sodium nitroprusside, and beta-hydroxybutyrate is not detected, so ketosis can be underestimated. Reference: Delanghe & Speeckaert, Preanalytical requirements of urinalysis, Biochem Med 2014 (pmc.ncbi.nlm.nih.gov/articles/PMC3936984); Simerville et al., Urinalysis: A Comprehensive Review, AFP 2005 (aafp.org/pubs/afp/issues/2005/0315/p1153.html).', '["Detected well.","Detected weakly (with glycine added).","Not a ketone with a keto group, so it is missed.","Beta-hydroxybutyrate is not detected."]'::jsonb, 2, 'verified'
