insert into questions (owner_id, topic_id, source, stem, choices, correct_index, explanation, choice_notes, difficulty, status)
select null, t.id, 'builtin', 'A positive urine nitrite test means bacteria in the urine can:', '["Reduce nitrate to nitrite","Oxidize nitrite to nitrate","Produce leukocyte esterase","Hydrolyze urea"]'::jsonb, 0, 'Nitrite is not normally in urine; it appears when bacteria reduce urinary nitrate to nitrite. A short bladder incubation time can give false-negative results. Reference: Simerville et al., Urinalysis: A Comprehensive Review, AFP 2005 (aafp.org/pubs/afp/issues/2005/0315/p1153.html); Delanghe & Speeckaert, Preanalytical requirements of urinalysis, Biochem Med 2014 (pmc.ncbi.nlm.nih.gov/articles/PMC3936984).', '["Gram-negative bacteria (e.g., E. coli) reduce nitrate; need about 4 hours in the bladder.","Reversed.","That is the WBC pad.","That is urease."]'::jsonb, 1, 'verified'
from topics t join subjects s on s.id = t.subject_id
where s.code = 'CM' and t.name = 'Chemical Exam of Urine'
  and not exists (select 1 from questions x where x.owner_id is null and x.stem_hash = md5(trim(regexp_replace(regexp_replace(lower('A positive urine nitrite test means bacteria in the urine can:'), '[^a-z0-9 ]', ' ', 'g'), '\s+', ' ', 'g'))));
update questions set choice_notes = '["Gram-negative bacteria (e.g., E. coli) reduce nitrate; need about 4 hours in the bladder.","Reversed.","That is the WBC pad.","That is urease."]'::jsonb
where owner_id is null and choice_notes is null and choices = '["Reduce nitrate to nitrite","Oxidize nitrite to nitrate","Produce leukocyte esterase","Hydrolyze urea"]'::jsonb and stem_hash = md5(trim(regexp_replace(regexp_replace(lower('A positive urine nitrite test means bacteria in the urine can:'), '[^a-z0-9 ]', ' ', 'g'), '\s+', ' ', 'g')));
insert into questions (owner_id, topic_id, source, stem, choices, correct_index, explanation, choice_notes, difficulty, status)
select null, t.id, 'builtin', 'The leukocyte esterase pad detects an enzyme produced mainly by:', '["Neutrophils","Red blood cells","Bacteria","Renal tubular cells"]'::jsonb, 0, 'Leukocyte esterase is produced by neutrophils, so a positive pad suggests pyuria from infection or inflammation. Reference: Hitzeman et al., Office-Based Urinalysis: A Comprehensive Review, AFP 2022 (aafp.org/pubs/afp/issues/2022/0700/office-based-urinalysis.html); Simerville et al., Urinalysis: A Comprehensive Review, AFP 2005 (aafp.org/pubs/afp/issues/2005/0315/p1153.html).', '["Granulocytes release esterase; also detects lysed WBCs.","RBCs do not make it.","Bacteria do not make it.","Renal cells do not make it."]'::jsonb, 1, 'verified'
from topics t join subjects s on s.id = t.subject_id
where s.code = 'CM' and t.name = 'Chemical Exam of Urine'
  and not exists (select 1 from questions x where x.owner_id is null and x.stem_hash = md5(trim(regexp_replace(regexp_replace(lower('The leukocyte esterase pad detects an enzyme produced mainly by:'), '[^a-z0-9 ]', ' ', 'g'), '\s+', ' ', 'g'))));
update questions set choice_notes = '["Granulocytes release esterase; also detects lysed WBCs.","RBCs do not make it.","Bacteria do not make it.","Renal cells do not make it."]'::jsonb
where owner_id is null and choice_notes is null and choices = '["Neutrophils","Red blood cells","Bacteria","Renal tubular cells"]'::jsonb and stem_hash = md5(trim(regexp_replace(regexp_replace(lower('The leukocyte esterase pad detects an enzyme produced mainly by:'), '[^a-z0-9 ]', ' ', 'g'), '\s+', ' ', 'g')));
insert into questions (owner_id, topic_id, source, stem, choices, correct_index, explanation, choice_notes, difficulty, status)
select null, t.id, 'builtin', 'Which substance can give a positive reagent strip blood test even when no red cells are present?', '["Bilirubin","Myoglobin","Urobilinogen","Glucose"]'::jsonb, 1, 'The blood pad detects peroxidase activity, which hemoglobin and myoglobin also have. So rhabdomyolysis (myoglobin) or hemolysis can give a positive result without RBCs. Reference: Simerville et al., Urinalysis: A Comprehensive Review, AFP 2005 (aafp.org/pubs/afp/issues/2005/0315/p1153.html).', '["Gives a positive bilirubin pad.","Myoglobin and free hemoglobin also have peroxidase activity.","Has its own pad.","Has its own pad."]'::jsonb, 2, 'verified'
from topics t join subjects s on s.id = t.subject_id
where s.code = 'CM' and t.name = 'Chemical Exam of Urine'
  and not exists (select 1 from questions x where x.owner_id is null and x.stem_hash = md5(trim(regexp_replace(regexp_replace(lower('Which substance can give a positive reagent strip blood test even when no red cells are present?'), '[^a-z0-9 ]', ' ', 'g'), '\s+', ' ', 'g'))));
update questions set choice_notes = '["Gives a positive bilirubin pad.","Myoglobin and free hemoglobin also have peroxidase activity.","Has its own pad.","Has its own pad."]'::jsonb
