insert into questions (owner_id, topic_id, source, stem, choices, correct_index, explanation, choice_notes, difficulty, status)
select null, t.id, 'builtin', 'Conjugated bilirubin found on a urine dipstick should prompt investigation for:', '["Urinary tract infection","Hepatobiliary disease","Diabetes mellitus","Kidney stones"]'::jsonb, 1, 'Only conjugated bilirubin is water-soluble enough to appear in urine. Its presence on dipstick should prompt a work-up for liver or bile duct disease. Reference: Hitzeman et al., Office-Based Urinalysis: A Comprehensive Review, AFP 2022 (aafp.org/pubs/afp/issues/2022/0700/office-based-urinalysis.html).', '["Not related.","Conjugated bilirubin passes into urine in liver disease or obstruction.","Not related.","Not related."]'::jsonb, 1, 'verified'
from topics t join subjects s on s.id = t.subject_id
where s.code = 'CM' and t.name = 'Chemical Exam of Urine'
  and not exists (select 1 from questions x where x.owner_id is null and x.stem_hash = md5(trim(regexp_replace(regexp_replace(lower('Conjugated bilirubin found on a urine dipstick should prompt investigation for:'), '[^a-z0-9 ]', ' ', 'g'), '\s+', ' ', 'g'))));
update questions set choice_notes = '["Not related.","Conjugated bilirubin passes into urine in liver disease or obstruction.","Not related.","Not related."]'::jsonb
where owner_id is null and choice_notes is null and choices = '["Urinary tract infection","Hepatobiliary disease","Diabetes mellitus","Kidney stones"]'::jsonb and stem_hash = md5(trim(regexp_replace(regexp_replace(lower('Conjugated bilirubin found on a urine dipstick should prompt investigation for:'), '[^a-z0-9 ]', ' ', 'g'), '\s+', ' ', 'g')));
insert into questions (owner_id, topic_id, source, stem, choices, correct_index, explanation, choice_notes, difficulty, status)
select null, t.id, 'builtin', 'In the Watson-Schwartz test, a red color that cannot be extracted into either chloroform or butanol indicates:', '["Urobilinogen","Porphobilinogen","Other Ehrlich-reactive compounds","Bilirubin"]'::jsonb, 1, 'The porphobilinogen-Ehrlich complex is a red chromogen that is insoluble in chloroform and N-butanol, while the urobilinogen-Ehrlich complex extracts into chloroform. Reference: Many pitfalls in diagnosis of acute intermittent porphyria: a case report (pmc.ncbi.nlm.nih.gov/articles/PMC6071335).', '["Extracts into chloroform and butanol.","Stays in the water layer; points to acute porphyria.","Extract into butanol, not chloroform.","Not detected by Ehrlich''s reagent."]'::jsonb, 3, 'verified'
from topics t join subjects s on s.id = t.subject_id
where s.code = 'CM' and t.name = 'Chemical Exam of Urine'
  and not exists (select 1 from questions x where x.owner_id is null and x.stem_hash = md5(trim(regexp_replace(regexp_replace(lower('In the Watson-Schwartz test, a red color that cannot be extracted into either chloroform or butanol indicates:'), '[^a-z0-9 ]', ' ', 'g'), '\s+', ' ', 'g'))));
update questions set choice_notes = '["Extracts into chloroform and butanol.","Stays in the water layer; points to acute porphyria.","Extract into butanol, not chloroform.","Not detected by Ehrlich''s reagent."]'::jsonb
where owner_id is null and choice_notes is null and choices = '["Urobilinogen","Porphobilinogen","Other Ehrlich-reactive compounds","Bilirubin"]'::jsonb and stem_hash = md5(trim(regexp_replace(regexp_replace(lower('In the Watson-Schwartz test, a red color that cannot be extracted into either chloroform or butanol indicates:'), '[^a-z0-9 ]', ' ', 'g'), '\s+', ' ', 'g')));
insert into questions (owner_id, topic_id, source, stem, choices, correct_index, explanation, choice_notes, difficulty, status)
select null, t.id, 'builtin', 'High urine ascorbic acid can cause false-negative reagent strip results for:', '["Blood and glucose","Protein and specific gravity","pH and protein","Urobilinogen and ketones"]'::jsonb, 0, 'Ascorbic acid is a strong reducing agent that causes false-negative results for glucose, hemoglobin (blood), nitrite and bilirubin. Reference: Ascorbic acid: A black hole of urine chemistry screening, J Clin Lab Anal 2019 (pmc.ncbi.nlm.nih.gov/articles/PMC6816895).', '["Ascorbic acid is a reducing agent that blocks the peroxide reactions.","Not affected.","Not affected.","Not the main pads affected."]'::jsonb, 2, 'verified'
