where s.code = 'CM' and t.name = 'Chemical Exam of Urine'
  and not exists (select 1 from questions x where x.owner_id is null and x.stem_hash = md5(trim(regexp_replace(regexp_replace(lower('High urine ascorbic acid can cause false-negative reagent strip results for:'), '[^a-z0-9 ]', ' ', 'g'), '\s+', ' ', 'g'))));
update questions set choice_notes = '["Ascorbic acid is a reducing agent that blocks the peroxide reactions.","Not affected.","Not affected.","Not the main pads affected."]'::jsonb
