insert into questions (owner_id, topic_id, source, stem, choices, correct_index, explanation, choice_notes, difficulty, status)
select null, t.id, 'builtin', 'Hyaline casts are made mainly of:', '["Albumin","Uromodulin (Tamm-Horsfall protein)","Fibrin","Immunoglobulin light chains"]'::jsonb, 1, 'Hyaline casts are a colorless fibrillary matrix of Tamm-Horsfall protein (uromodulin), the protein that forms the base of all casts. Reference: Gaggar & Raju, Diagnostic Utility of Urine Microscopy in Kidney Diseases, Indian J Nephrol 2024 (pmc.ncbi.nlm.nih.gov/articles/PMC11303840); Simerville et al., Urinalysis: A Comprehensive Review, AFP 2005 (aafp.org/pubs/afp/issues/2005/0315/p1153.html).', '["Proteins leak in glomerular disease but do not form the hyaline matrix.","Made by the distal tubule and ascending loop cells.","Not the matrix.","Not the matrix."]'::jsonb, 1, 'verified'
