insert into questions (owner_id, topic_id, source, stem, choices, correct_index, explanation, choice_notes, difficulty, status)
select null, t.id, 'builtin', 'RBC casts in urine are most suggestive of:', '["Acute glomerulonephritis","Cystitis","Lower urinary tract bleeding","Acute pyelonephritis"]'::jsonb, 0, 'RBC casts are generally associated with glomerular disease such as glomerulonephritis. Lower urinary tract bleeding gives free RBCs without casts. Reference: Gaggar & Raju, Diagnostic Utility of Urine Microscopy in Kidney Diseases, Indian J Nephrol 2024 (pmc.ncbi.nlm.nih.gov/articles/PMC11303840); Simerville et al., Urinalysis: A Comprehensive Review, AFP 2005 (aafp.org/pubs/afp/issues/2005/0315/p1153.html).', '["Bleeding from the glomerulus.","Lower tract; no casts.","No casts form below the kidney.","Shows WBC casts."]'::jsonb, 1, 'verified'
