select null, t.id, 'builtin', 'Which CSF finding points to a traumatic tap rather than a subarachnoid hemorrhage?', '["Blood that decreases from tube 1 to tube 3","Xanthochromic supernatant","Erythrophages in the sediment","Hemosiderin-laden macrophages"]'::jsonb, 0, 'In a traumatic tap the red cells fall markedly from the first to the last tube (about 60% has been proposed). Xanthochromia and erythrophagocytosis point to blood that was already there (hemorrhage). Reference: Subarachnoid haemorrhage or traumatic lumbar puncture: differentiation by CSF parameters (pmc.ncbi.nlm.nih.gov/articles/PMC10724187); CSF in acute and chronic infectious diseases (pmc.ncbi.nlm.nih.gov/articles/PMC7150022).', '["Needle injury gives most blood in the first tube.","Points to a real bleed (older than a few hours).","Points to a real bleed.","Points to an older bleed."]'::jsonb, 2, 'verified'
