select null, t.id, 'builtin', 'A stool pH below 5.5 with a positive test for reducing substances suggests:', '["Carbohydrate malabsorption or intolerance","Pancreatic fat malabsorption","Upper GI bleeding","Bile duct obstruction"]'::jsonb, 0, 'A fecal pH below 5.5 means acidic stool, and reducing substances are tested when carbohydrate malabsorption is suspected, because unabsorbed sugars are fermented into acids. Reference: Kasirga, The importance of stool tests in diagnosis and follow-up of gastrointestinal disorders in children, Turk Pediatri Ars 2019 (pmc.ncbi.nlm.nih.gov/articles/PMC6776453).', '["Unabsorbed sugars ferment and make acid.","Shows fat on Sudan stain, not low pH.","Shows a positive occult blood test.","Shows pale stools."]'::jsonb, 3, 'verified'
from topics t join subjects s on s.id = t.subject_id
where s.code = 'CM' and t.name = 'Fecalysis'
  and not exists (select 1 from questions x where x.owner_id is null and x.stem_hash = md5(trim(regexp_replace(regexp_replace(lower('A stool pH below 5.5 with a positive test for reducing substances suggests:'), '[^a-z0-9 ]', ' ', 'g'), '\s+', ' ', 'g'))));
update questions set choice_notes = '["Unabsorbed sugars ferment and make acid.","Shows fat on Sudan stain, not low pH.","Shows a positive occult blood test.","Shows pale stools."]'::jsonb
where owner_id is null and choice_notes is null and choices = '["Carbohydrate malabsorption or intolerance","Pancreatic fat malabsorption","Upper GI bleeding","Bile duct obstruction"]'::jsonb and stem_hash = md5(trim(regexp_replace(regexp_replace(lower('A stool pH below 5.5 with a positive test for reducing substances suggests:'), '[^a-z0-9 ]', ' ', 'g'), '\s+', ' ', 'g')));

commit;
